// src/App.js
import React from "react";
import { Routes, Route, NavLink } from "react-router-dom";
import Home from "./pages/Home";
import Predict from "./pages/Predict";
import History from "./pages/History";

export default function App() {
  return (
    <div style={appStyle}>
      {/* Navbar */}
      <nav style={navStyle}>
        <div style={logoStyle}>Company Growth Analytics</div>

        <div style={navLinks}>
          <NavLink to="/" style={linkStyle}>
            Home
          </NavLink>
          <NavLink to="/predict" style={linkStyle}>
            Predict
          </NavLink>
          <NavLink to="/history" style={linkStyle}>
            History
          </NavLink>
        </div>
      </nav>

      {/* Page Content */}
      <main style={mainStyle}>
        <div style={pageCard}>
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/predict" element={<Predict />} />
            <Route path="/history" element={<History />} />
          </Routes>
        </div>
      </main>

      {/* Footer */}
      <footer style={footerStyle}>
        © 2026 Company Growth Analytics • Machine Learning Dashboard
      </footer>
    </div>
  );
}

/* ---------- Styles ---------- */

const appStyle = {
  fontFamily: "'Inter', Arial, sans-serif",
  minHeight: "100vh",
  display: "flex",
  flexDirection: "column",
  background: "linear-gradient(135deg, #eef2f3, #dfe9f3)"
};

const navStyle = {
  display: "flex",
  justifyContent: "space-between",
  alignItems: "center",
  padding: "18px 40px",
  background: "#4CAF50",
  color: "white",
  boxShadow: "0 3px 10px rgba(0,0,0,0.1)"
};

const logoStyle = {
  fontWeight: "bold",
  fontSize: "18px",
  letterSpacing: "0.5px"
};

const navLinks = {
  display: "flex",
  gap: "30px"
};

const linkStyle = ({ isActive }) => ({
  color: "white",
  textDecoration: "none",
  fontWeight: "600",
  padding: "6px 12px",
  borderRadius: "6px",
  transition: "all 0.25s ease",
  backgroundColor: isActive ? "rgba(255,255,255,0.2)" : "transparent"
});

const mainStyle = {
  flex: 1,
  padding: "40px",
  display: "flex",
  justifyContent: "center",
  alignItems: "flex-start"
};

const pageCard = {
  width: "100%",
  maxWidth: "1200px",
  background: "white",
  padding: "35px",
  borderRadius: "14px",
  boxShadow: "0 8px 25px rgba(0,0,0,0.08)",
  animation: "fadeIn 0.3s ease"
};

const footerStyle = {
  textAlign: "center",
  padding: "15px",
  background: "#4CAF50",
  color: "white",
  fontSize: "14px"
};
